import json, collections

domain = params.get('domain', 'AE').upper()
data = state_data.get('read_sdtm', {}).get('records', [])

if not data:
    result = {'summary': f'No {domain} data found.', 'record_count': 0}
else:
    count = len(data)
    key_fields = {
        'AE': ['AETERM', 'AESEV', 'AESER', 'AEOUT'],
        'LB': ['LBTEST', 'LBSTRESN', 'LBNRIND'],
        'VS': ['VSTESTCD', 'VSSTRESN'],
        'DM': ['SEX', 'RACE', 'AGE'],
    }.get(domain, [])

    freq = {}
    for field in key_fields:
        vals = [r.get(field) for r in data if r.get(field)]
        if vals:
            freq[field] = dict(collections.Counter(vals).most_common(5))

    result = {
        'summary': f'{count} {domain} records found.',
        'record_count': count,
        'key_frequencies': freq,
    }
